from pathlib import Path
import json
import subprocess
import sys
root=Path(__file__).resolve().parent.parent
base=root/'2027年企业命题'; gen=root/'_gen'
# update text and rename topic directories; docs/PDFs are regenerated by build.py afterward
for code,name in [('E01','益普索'),('E02','问卷网'),('E03','同方知网'),('E04','格远数智赋能'),('E05','汇辽集团'),('E06','酷冷保温'),('E07','神启数据'),('E08','中健国康')]:
    rows=json.loads((gen/f'{code}.json').read_text(encoding='utf-8-sig'))
    cdir=base/f'{code}_{name}'
    for r in rows:
        oldprefix=f"{r['id']}_"
        candidates=[p for p in cdir.iterdir() if p.is_dir() and p.name.startswith(oldprefix)]
        if len(candidates)!=1: raise RuntimeError(f'{r["id"]}: expected one old dir, got {len(candidates)}')
        old=candidates[0]; new=cdir/(r['id']+'_'+r['full_title'])
        if old != new:
            old.rename(new)
        topic_txt='\n'.join([
            f"{r['id']}. {r['full_title']}",
            f"- **企业命题**：{name} · {r['company_bucket']}",
            f"- **对象**：{r['object']}",f"- **变量**：{r['variables']}",
            f"- **行业**：{r['industry']}",f"- **地域**：{r['region']}",f"- **阶段**：{r['stage']}",
            f"- **假设**：H1：{r['h1']}；H2：{r['h2']}",f"- **可行性**：{r['feasibility']}",
            f"- **参考来源**：{r['sources']}",f"- **命题呼应**：{r['fit_note']}" ])+'\n'
        (new/'_topic.txt').write_text(topic_txt,encoding='utf-8')
print('renamed and refreshed metadata')
